#!/usr/bin/env bash
set -euo pipefail

REQUIRED_BASE_COMMIT="4b54bdef1f5c29d84d566c3eb1ecc21214bf8dd9"
TARGET_BRANCH="${1:-feature/kosmora-windows-final-acceptance}"

echo "[1/5] Fetching latest origin/main..."
git fetch origin main

if ! git merge-base --is-ancestor "$REQUIRED_BASE_COMMIT" origin/main; then
  echo "ERROR: origin/main does not contain required base commit $REQUIRED_BASE_COMMIT" >&2
  exit 1
fi

if git show-ref --verify --quiet "refs/remotes/origin/$TARGET_BRANCH"; then
  TARGET_BRANCH="${TARGET_BRANCH}-$(date +%Y%m%d-%H%M%S)"
  echo "Branch name already exists on remote; using unique branch: $TARGET_BRANCH"
fi

echo "[2/5] Creating branch $TARGET_BRANCH from origin/main..."
git checkout -B "$TARGET_BRANCH" origin/main

echo "[3/5] Applying Kosmora Windows final acceptance files..."
python3 - <<'INNER_PY'
import base64, io, tarfile
payload = base64.b64decode('''''')
with tarfile.open(fileobj=io.BytesIO(payload), mode="r:gz") as tf:
    tf.extractall(".")
INNER_PY

echo "[4/5] Running syntax, unit, and unsigned policy verification..."
npm --prefix desktop/windows run check
npm --prefix desktop/windows run verify:unsigned

echo "[5/5] Committing changes on $TARGET_BRANCH..."
git add desktop/windows .github/workflows/windows-desktop.yml docs/handoff/WINDOWS_FINAL_ACCEPTANCE.md
git commit -m "feat(windows): finalize Kosmora Windows client acceptance, recovery, download center, and packaged GUI CI"

echo "Ready! To push and open PR:"
echo "  git push -u origin $TARGET_BRANCH"
